const rows = document.querySelectorAll('div[aria-label="Issues"] [data-listview-component="row"], .js-issue-row');
const out = [];
for (const r of Array.from(rows).slice(0, args.limit ?? 30)) {
  const titleA = r.querySelector('a[id^="issue_"], a.markdown-title, h3 a');
  const title = titleA?.textContent?.trim();
  const href = titleA?.getAttribute('href');
  const numberM = href?.match(/\/(?:issues|pull)\/(\d+)/);
  const labels = Array.from(r.querySelectorAll('a.IssueLabel, [data-testid="issue-label"]')).map(l => l.textContent.trim());
  out.push({ title, number: numberM ? Number(numberM[1]) : null, href, labels });
}
return { count: out.length, issues: out };

if (!location.pathname.match(/\/pull\/\d+/)) return { error: 'not on a PR page', url: location.href };
return {
  title: document.querySelector('.gh-header-title bdi, .js-issue-title')?.textContent?.trim(),
  number: location.pathname.match(/\/pull\/(\d+)/)?.[1],
  state: document.querySelector('.State')?.textContent?.trim(),
  author: document.querySelector('.gh-header-meta a.author')?.textContent?.trim(),
  files_changed: document.querySelector('#files_tab_counter')?.textContent?.trim(),
  additions: document.querySelector('.diffstat .text-success')?.textContent?.trim(),
  deletions: document.querySelector('.diffstat .text-danger')?.textContent?.trim(),
  url: location.href,
};

const rows = document.querySelectorAll('table[aria-labelledby="folders-and-files"] tr.react-directory-row, .Box-row.js-navigation-item');
const out = [];
for (const r of rows) {
  const link = r.querySelector('a[href]');
  if (!link) continue;
  out.push({ name: link.textContent.trim(), href: link.getAttribute('href'), kind: r.querySelector('[aria-label*="Directory"]') ? 'dir' : 'file' });
}
return { entries: out };
